+// Electron main process entry point.
+
+import { app, BrowserWindow, ipcMain, shell } from "electron";
+import path from "node:path";
+
+import { Sidecar } from "./sidecar";
+import { applyEvent, getFlow, listFlows, summarize } from "./db";
+import type { CaptureEvent, FlowSummary } from "@shared/types";
+
+let mainWindow: BrowserWindow | null = null;
+const sidecar = new Sidecar();
+
+function createWindow(): void {
+  mainWindow = new BrowserWindow({
+    width: 1200,
+    height: 800,
+    minWidth: 800,
+    minHeight: 500,
+    titleBarStyle: "hiddenInset",
+    backgroundColor: "#0b0f14",
+    webPreferences: {
+      preload: path.join(__dirname, "../preload/index.js"),
+      sandbox: false,
+      contextIsolation: true,
+    },
+  });
+
+  // Open external links in the system browser.
+  mainWindow.webContents.setWindowOpenHandler(({ url }) => {
+    shell.openExternal(url);
+    return { action: "deny" };
+  });
+
+  const devUrl = process.env["ELECTRON_RENDERER_URL"];
+  if (!app.isPackaged && devUrl) {
+    void mainWindow.loadURL(devUrl);
+    mainWindow.webContents.openDevTools({ mode: "detach" });
+  } else {
+    void mainWindow.loadFile(path.join(__dirname, "../renderer/index.html"));
+  }
+
+  mainWindow.on("closed", () => {
+    mainWindow = null;
+  });
+}
+
+function registerIpc(): void {
+  ipcMain.handle("reflex:list-flows", (_e, limit?: number) =>
+    listFlows(limit ?? 200),
+  );
+  ipcMain.handle("reflex:get-flow", (_e, id: string) => getFlow(id));
+  ipcMain.handle("reflex:status", () => sidecar.getStatus());
+}
+
+function wireSidecar(): void {
+  sidecar.on("event", (ev: CaptureEvent) => {
+    const touched = applyEvent(ev);
+    if (touched) {
+      const summary: FlowSummary | null = summarize(touched);
+      if (summary && mainWindow && !mainWindow.isDestroyed()) {
+        mainWindow.webContents.send("reflex:flow", summary);
+      }
+    }
+  });
+
+  sidecar.on("status", (status) => {
+    if (mainWindow && !mainWindow.isDestroyed()) {
+      mainWindow.webContents.send("reflex:status", status);
+    }
+  });
+}
+
+app.whenReady().then(() => {
+  registerIpc();
+  wireSidecar();
+  sidecar.start();
+  createWindow();
+
+  app.on("activate", () => {
+    if (BrowserWindow.getAllWindows().length === 0) createWindow();
+  });
+});
+
+app.on("window-all-closed", () => {
+  if (process.platform !== "darwin") app.quit();
+});
+
+app.on("before-quit", () => {
+  sidecar.stop();
+});

