export type Headers = Record<string, string>;

export type CaptureEvent =
  | {
      type: "sidecar_ready";
      proxy_port: number;
      ws_port: number;
      ca_cert_path: string;
      ca_fingerprint_sha256: string;
    }
  | {
      type: "flow_start";
      id: string;
      ts: string;
      method: string;
      scheme: string;
      host: string;
      port: number;
      path: string;
      url: string;
      http_version: string;
    }
  | {
      type: "request_head";
      id: string;
      headers: Headers;
    }
  | {
      type: "request_body";
      id: string;
      body_b64: string;
      truncated: boolean;
      byte_len: number;
    }
  | {
      type: "response_head";
      id: string;
      status: number;
      http_version: string;
      headers: Headers;
    }
  | {
      type: "response_body";
      id: string;
      body_b64: string;
      truncated: boolean;
      byte_len: number;
    }
  | {
      type: "flow_end";
      id: string;
      duration_ms: number;
      error: string | null;
    };

// Domain types surfaced to the renderer.
export interface FlowSummary {
  id: string;
  ts: string;
  method: string;
  host: string;
  path: string;
  url: string;
  status: number | null;
  duration_ms: number | null;
  request_bytes: number;
  response_bytes: number;
  error: string | null;
}

export interface FlowDetail extends FlowSummary {
  scheme: string;
  port: number;
  http_version: string;
  request_headers: Headers;
  response_headers: Headers;
  /** base64 */
  request_body: string | null;
  /** base64 */
  response_body: string | null;
  request_truncated: boolean;
  response_truncated: boolean;
}

// Bridge surface exposed to the renderer via preload/contextBridge.
export interface ReflexBridge {
  listFlows(limit?: number): Promise<FlowSummary[]>;
  getFlow(id: string): Promise<FlowDetail | null>;
  /** Subscribe to live flow summaries; returns an unsubscribe fn. */
  onFlow(cb: (flow: FlowSummary) => void): () => void;
  /** Capture subsystem status for the status bar. */
  getStatus(): Promise<CaptureStatus>;
}

export interface CaptureStatus {
  sidecarRunning: boolean;
  proxyPort: number | null;
  wsPort: number | null;
  caCertPath: string | null;
  caFingerprintSha256: string | null;
  lastError: string | null;
}

// Spawns the Rust capture sidecar, parses its stdout for the `sidecar_ready`
// announcement, then opens a WebSocket to it and relays events.

import { spawn, ChildProcess } from "node:child_process";
import { app } from "electron";
import path from "node:path";
import fs from "node:fs";
import readline from "node:readline";
import { EventEmitter } from "node:events";
import WebSocket from "ws";

import type { CaptureEvent, CaptureStatus } from "@shared/types";

const HOST_ALLOWLIST = [
  "api.openai.com",
  "api.anthropic.com",
  "chat.openai.com",
  "claude.ai",
  "api.cursor.sh",
  "generativelanguage.googleapis.com",
  "api.x.ai",
];

export interface SidecarEvents {
  event: (ev: CaptureEvent) => void;
  status: (status: CaptureStatus) => void;
}

export class Sidecar extends EventEmitter {
  private child: ChildProcess | null = null;
  private ws: WebSocket | null = null;
  private status: CaptureStatus = {
    sidecarRunning: false,
    proxyPort: null,
    wsPort: null,
    caCertPath: null,
    caFingerprintSha256: null,
    lastError: null,
  };

  getStatus(): CaptureStatus {
    return { ...this.status };
  }

  start(): void {
    if (this.child) return;

    const bin = resolveBinary();
    if (!bin) {
      this.updateStatus({
        lastError: "capture sidecar binary not found — run `pnpm build:sidecar`",
      });
      return;
    }

    const dataDir = path.join(app.getPath("userData"), "capture");
    fs.mkdirSync(dataDir, { recursive: true });

    const env = {
      ...process.env,
      REFLEX_DATA_DIR: dataDir,
      REFLEX_ALLOW_HOSTS: HOST_ALLOWLIST.join(","),
      REFLEX_LOG: process.env.REFLEX_LOG ?? "info",
    };

    const args = ["--proxy-port", "8888", "--ws-port", "0"];

    console.log(`[sidecar] spawning ${bin} ${args.join(" ")}`);
    const child = spawn(bin, args, { env, stdio: ["ignore", "pipe", "pipe"] });
    this.child = child;

    // stderr is free-form tracing logs — just forward to stdout.
    child.stderr?.on("data", (chunk) =>
      process.stderr.write(`[sidecar] ${chunk}`),
    );

    // stdout carries the `sidecar_ready` JSON line (and only that line today).
    const rl = readline.createInterface({ input: child.stdout! });
    rl.on("line", (line) => this.onSidecarStdout(line));

    child.once("exit", (code, signal) => {
      console.warn(`[sidecar] exited code=${code} signal=${signal}`);
      this.child = null;
      this.ws?.close();
      this.ws = null;
      this.updateStatus({ sidecarRunning: false });
    });

    child.once("error", (err) => {
      this.updateStatus({ lastError: err.message, sidecarRunning: false });
    });
  }

  stop(): void {
    this.ws?.close();
    this.ws = null;
    if (this.child && !this.child.killed) {
      this.child.kill("SIGTERM");
    }
    this.child = null;
    this.updateStatus({ sidecarRunning: false });
  }

  private onSidecarStdout(line: string): void {
    const trimmed = line.trim();
    if (!trimmed) return;
    let ev: CaptureEvent;
    try {
      ev = JSON.parse(trimmed);
    } catch (err) {
      console.warn("[sidecar] non-JSON stdout line:", trimmed);
      return;
    }
    if (ev.type === "sidecar_ready") {
      this.updateStatus({
        sidecarRunning: true,
        proxyPort: ev.proxy_port,
        wsPort: ev.ws_port,
        caCertPath: ev.ca_cert_path,
        caFingerprintSha256: ev.ca_fingerprint_sha256,
        lastError: null,
      });
      this.connectWs(ev.ws_port);
    }
  }

  private connectWs(port: number): void {
    const url = `ws://127.0.0.1:${port}`;
    console.log(`[sidecar] connecting WS → ${url}`);
    const ws = new WebSocket(url);
    this.ws = ws;

    ws.on("open", () => console.log("[sidecar] WS open"));
    ws.on("close", () => {
      console.log("[sidecar] WS close");
      this.ws = null;
    });
    ws.on("error", (err) => {
      console.warn("[sidecar] WS error:", err.message);
      this.updateStatus({ lastError: err.message });
    });
    ws.on("message", (data) => {
      const text = data.toString("utf8");
      let ev: CaptureEvent;
      try {
        ev = JSON.parse(text);
      } catch {
        return;
      }
      this.emit("event", ev);
    });
  }

  private updateStatus(patch: Partial<CaptureStatus>): void {
    this.status = { ...this.status, ...patch };
    this.emit("status", this.getStatus());
  }
}

function resolveBinary(): string | null {
  // 1. Packaged: out/main/../resources/capture (extraResources)
  // 2. Dev: electron/resources/capture (produced by scripts/build-sidecar.sh)
  // 3. Dev fallback: ../rust/target/debug/reflex-capture
  const candidates = [
    app.isPackaged
      ? path.join(process.resourcesPath, "capture")
      : path.join(app.getAppPath(), "resources", "capture"),
    path.join(app.getAppPath(), "..", "rust", "target", "release", "reflex-capture"),
    path.join(app.getAppPath(), "..", "rust", "target", "debug", "reflex-capture"),
  ];
  for (const c of candidates) {
    try {
      fs.accessSync(c, fs.constants.X_OK);
      return c;
    } catch {
      // continue
    }
  }
  return null;
}

// SQLite store for captured flows. One DB file per user.
//
// The schema is intentionally denormalized so that a UI query for the
// flow list is a single SELECT over one table.

import Database from "better-sqlite3";
import path from "node:path";
import fs from "node:fs";
import { app } from "electron";

import type { CaptureEvent, FlowDetail, FlowSummary } from "@shared/types";

let db: Database.Database | null = null;

export function open(): Database.Database {
  if (db) return db;
  const dir = path.join(app.getPath("userData"), "reflex");
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, "flows.db");
  db = new Database(file);
  db.pragma("journal_mode = WAL");
  db.pragma("synchronous = NORMAL");
  db.exec(SCHEMA);
  return db;
}

const SCHEMA = `
CREATE TABLE IF NOT EXISTS flows (
  id TEXT PRIMARY KEY,
  ts TEXT NOT NULL,
  method TEXT NOT NULL,
  scheme TEXT NOT NULL,
  host TEXT NOT NULL,
  port INTEGER NOT NULL,
  path TEXT NOT NULL,
  url TEXT NOT NULL,
  http_version TEXT NOT NULL,
  status INTEGER,
  duration_ms INTEGER,
  request_bytes INTEGER NOT NULL DEFAULT 0,
  response_bytes INTEGER NOT NULL DEFAULT 0,
  request_headers TEXT NOT NULL DEFAULT '{}',
  response_headers TEXT NOT NULL DEFAULT '{}',
  request_body BLOB,
  response_body BLOB,
  request_truncated INTEGER NOT NULL DEFAULT 0,
  response_truncated INTEGER NOT NULL DEFAULT 0,
  error TEXT
);

CREATE INDEX IF NOT EXISTS idx_flows_ts ON flows(ts DESC);
CREATE INDEX IF NOT EXISTS idx_flows_host ON flows(host);
`;

/** Apply a single capture event to the DB. Returns the flow id if a summary
 *  should be pushed to the renderer (flow_start / flow_end moments). */
export function applyEvent(ev: CaptureEvent): string | null {
  const d = open();
  switch (ev.type) {
    case "flow_start":
      d.prepare(
        `INSERT OR REPLACE INTO flows
         (id, ts, method, scheme, host, port, path, url, http_version)
         VALUES (@id, @ts, @method, @scheme, @host, @port, @path, @url, @http_version)`,
      ).run({
        id: ev.id,
        ts: ev.ts,
        method: ev.method,
        scheme: ev.scheme,
        host: ev.host,
        port: ev.port,
        path: ev.path,
        url: ev.url,
        http_version: ev.http_version,
      });
      return ev.id;

    case "request_head":
      d.prepare(`UPDATE flows SET request_headers = ? WHERE id = ?`).run(
        JSON.stringify(ev.headers),
        ev.id,
      );
      return null;

    case "request_body": {
      const buf = Buffer.from(ev.body_b64, "base64");
      d.prepare(
        `UPDATE flows SET request_body = ?, request_bytes = ?, request_truncated = ? WHERE id = ?`,
      ).run(buf, ev.byte_len, ev.truncated ? 1 : 0, ev.id);
      return null;
    }

    case "response_head":
      d.prepare(
        `UPDATE flows SET status = ?, http_version = ?, response_headers = ? WHERE id = ?`,
      ).run(ev.status, ev.http_version, JSON.stringify(ev.headers), ev.id);
      return null;

    case "response_body": {
      const buf = Buffer.from(ev.body_b64, "base64");
      d.prepare(
        `UPDATE flows SET response_body = ?, response_bytes = ?, response_truncated = ? WHERE id = ?`,
      ).run(buf, ev.byte_len, ev.truncated ? 1 : 0, ev.id);
      return null;
    }

    case "flow_end":
      d.prepare(
        `UPDATE flows SET duration_ms = ?, error = ? WHERE id = ?`,
      ).run(ev.duration_ms, ev.error, ev.id);
      return ev.id;

    default:
      return null;
  }
}

export function listFlows(limit = 200): FlowSummary[] {
  const d = open();
  const rows = d
    .prepare(
      `SELECT id, ts, method, host, path, url, status, duration_ms,
              request_bytes, response_bytes, error
       FROM flows
       ORDER BY ts DESC
       LIMIT ?`,
    )
    .all(limit) as FlowSummary[];
  return rows;
}

export function getFlow(id: string): FlowDetail | null {
  const d = open();
  const row = d
    .prepare(`SELECT * FROM flows WHERE id = ?`)
    .get(id) as Record<string, unknown> | undefined;
  if (!row) return null;

  const reqHeaders = safeJson(row.request_headers as string) ?? {};
  const resHeaders = safeJson(row.response_headers as string) ?? {};

  const reqBody = row.request_body as Buffer | null;
  const resBody = row.response_body as Buffer | null;

  return {
    id: row.id as string,
    ts: row.ts as string,
    method: row.method as string,
    scheme: row.scheme as string,
    host: row.host as string,
    port: row.port as number,
    path: row.path as string,
    url: row.url as string,
    http_version: row.http_version as string,
    status: (row.status as number | null) ?? null,
    duration_ms: (row.duration_ms as number | null) ?? null,
    request_bytes: (row.request_bytes as number) ?? 0,
    response_bytes: (row.response_bytes as number) ?? 0,
    request_headers: reqHeaders,
    response_headers: resHeaders,
    request_body: reqBody ? reqBody.toString("base64") : null,
    response_body: resBody ? resBody.toString("base64") : null,
    request_truncated: !!row.request_truncated,
    response_truncated: !!row.response_truncated,
    error: (row.error as string | null) ?? null,
  };
}

function safeJson(s: string | null | undefined): Record<string, string> | null {
  if (!s) return null;
  try {
    return JSON.parse(s);
  } catch {
    return null;
  }
}

/** Build a lightweight summary from the current DB row (for renderer push). */
export function summarize(id: string): FlowSummary | null {
  const d = open();
  const row = d
    .prepare(
      `SELECT id, ts, method, host, path, url, status, duration_ms,
              request_bytes, response_bytes, error
       FROM flows WHERE id = ?`,
    )
    .get(id) as FlowSummary | undefined;
  return row ?? null;
}

// Electron main process entry point.

import { app, BrowserWindow, ipcMain, shell } from "electron";
import path from "node:path";

import { Sidecar } from "./sidecar";
import { applyEvent, getFlow, listFlows, summarize } from "./db";
import type { CaptureEvent, FlowSummary } from "@shared/types";

let mainWindow: BrowserWindow | null = null;
const sidecar = new Sidecar();

function createWindow(): void {
  mainWindow = new BrowserWindow({
    width: 1200,
    height: 800,
    minWidth: 800,
    minHeight: 500,
    titleBarStyle: "hiddenInset",
    backgroundColor: "#0b0f14",
    webPreferences: {
      preload: path.join(__dirname, "../preload/index.js"),
      sandbox: false,
      contextIsolation: true,
    },
  });

  // Open external links in the system browser.
  mainWindow.webContents.setWindowOpenHandler(({ url }) => {
    shell.openExternal(url);
    return { action: "deny" };
  });

  const devUrl = process.env["ELECTRON_RENDERER_URL"];
  if (!app.isPackaged && devUrl) {
    void mainWindow.loadURL(devUrl);
    mainWindow.webContents.openDevTools({ mode: "detach" });
  } else {
    void mainWindow.loadFile(path.join(__dirname, "../renderer/index.html"));
  }

  mainWindow.on("closed", () => {
    mainWindow = null;
  });
}

function registerIpc(): void {
  ipcMain.handle("reflex:list-flows", (_e, limit?: number) =>
    listFlows(limit ?? 200),
  );
  ipcMain.handle("reflex:get-flow", (_e, id: string) => getFlow(id));
  ipcMain.handle("reflex:status", () => sidecar.getStatus());
}

function wireSidecar(): void {
  sidecar.on("event", (ev: CaptureEvent) => {
    const touched = applyEvent(ev);
    if (touched) {
      const summary: FlowSummary | null = summarize(touched);
      if (summary && mainWindow && !mainWindow.isDestroyed()) {
        mainWindow.webContents.send("reflex:flow", summary);
      }
    }
  });

  sidecar.on("status", (status) => {
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send("reflex:status", status);
    }
  });
}

app.whenReady().then(() => {
  registerIpc();
  wireSidecar();
  sidecar.start();
  createWindow();

  app.on("activate", () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

app.on("window-all-closed", () => {
  if (process.platform !== "darwin") app.quit();
});

app.on("before-quit", () => {
  sidecar.stop();
});

import { contextBridge, ipcRenderer } from "electron";
import type {
  CaptureStatus,
  FlowDetail,
  FlowSummary,
} from "../shared/types";

const api = {
  listFlows: (limit?: number): Promise<FlowSummary[]> =>
    ipcRenderer.invoke("reflex:list-flows", limit),

  getFlow: (id: string): Promise<FlowDetail | null> =>
    ipcRenderer.invoke("reflex:get-flow", id),

  getStatus: (): Promise<CaptureStatus> => ipcRenderer.invoke("reflex:status"),

  onFlow: (cb: (flow: FlowSummary) => void): (() => void) => {
    const handler = (_e: Electron.IpcRendererEvent, flow: FlowSummary): void =>
      cb(flow);
    ipcRenderer.on("reflex:flow", handler);
    return () => ipcRenderer.off("reflex:flow", handler);
  },

  onStatus: (cb: (status: CaptureStatus) => void): (() => void) => {
    const handler = (
      _e: Electron.IpcRendererEvent,
      status: CaptureStatus,
    ): void => cb(status);
    ipcRenderer.on("reflex:status", handler);
    return () => ipcRenderer.off("reflex:status", handler);
  },
};

contextBridge.exposeInMainWorld("reflex", api);

