import { useCallback, useEffect, useMemo, useState } from "react";

import type {
  CaptureStatus,
  FlowDetail,
  FlowSummary,
} from "../../shared/types";
import { FlowList } from "./components/FlowList";
import { FlowDetailView } from "./components/FlowDetail";
import { StatusBar } from "./components/StatusBar";

export function App(): JSX.Element {
  const [flows, setFlows] = useState<FlowSummary[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [detail, setDetail] = useState<FlowDetail | null>(null);
  const [status, setStatus] = useState<CaptureStatus | null>(null);

  // Initial load.
  useEffect(() => {
    void window.reflex.listFlows(500).then(setFlows);
    void window.reflex.getStatus().then(setStatus);
  }, []);

  // Live flow stream.
  useEffect(() => {
    return window.reflex.onFlow((flow) => {
      setFlows((prev) => {
        // de-dupe by id, prepend/update
        const idx = prev.findIndex((f) => f.id === flow.id);
        if (idx >= 0) {
          const next = prev.slice();
          next[idx] = flow;
          return next;
        }
        return [flow, ...prev].slice(0, 1000);
      });
    });
  }, []);

  // Status updates.
  useEffect(() => {
    return window.reflex.onStatus(setStatus);
  }, []);

  // Load detail on selection.
  useEffect(() => {
    if (!selectedId) {
      setDetail(null);
      return;
    }
    void window.reflex.getFlow(selectedId).then(setDetail);
  }, [selectedId]);

  const handleSelect = useCallback((id: string) => setSelectedId(id), []);

  const header = useMemo(
    () => (
      <header className="flex h-10 shrink-0 items-center justify-between border-b border-slate-800 px-4">
        <div className="flex items-center gap-2 text-sm font-medium">
          <span className="inline-block h-2 w-2 rounded-full bg-emerald-500" />
          <span>Reflex</span>
          <span className="text-slate-500">· capture</span>
        </div>
        <div className="text-xs text-slate-500">
          {flows.length} flow{flows.length === 1 ? "" : "s"}
        </div>
      </header>
    ),
    [flows.length],
  );

  return (
    <div className="flex h-full flex-col font-mono text-sm">
      {header}
      <div className="flex min-h-0 flex-1">
        <aside className="w-[420px] shrink-0 overflow-y-auto border-r border-slate-800">
          <FlowList
            flows={flows}
            selectedId={selectedId}
            onSelect={handleSelect}
          />
        </aside>
        <main className="min-w-0 flex-1 overflow-y-auto">
          <FlowDetailView flow={detail} />
        </main>
      </div>
      <StatusBar status={status} />
    </div>
  );
}

import type { FlowSummary } from "../../../shared/types";

interface Props {
  flows: FlowSummary[];
  selectedId: string | null;
  onSelect: (id: string) => void;
}

export function FlowList({ flows, selectedId, onSelect }: Props): JSX.Element {
  if (flows.length === 0) {
    return (
      <div className="p-6 text-slate-500">
        No flows yet. Start an AI app while Reflex is running —
        traffic matching the host allowlist will appear here.
      </div>
    );
  }

  return (
    <ul className="divide-y divide-slate-800">
      {flows.map((f) => (
        <li key={f.id}>
          <button
            onClick={() => onSelect(f.id)}
            className={`flex w-full flex-col gap-0.5 px-3 py-2 text-left transition hover:bg-slate-900 ${
              selectedId === f.id ? "bg-slate-900" : ""
            }`}
          >
            <div className="flex items-center gap-2 text-xs">
              <StatusBadge status={f.status} error={f.error} />
              <span className="font-semibold text-slate-300">{f.method}</span>
              <span className="truncate text-slate-400">{f.host}</span>
              {f.duration_ms !== null && (
                <span className="ml-auto shrink-0 tabular-nums text-slate-500">
                  {f.duration_ms}ms
                </span>
