Index: electron/src/main/sidecar.ts
===================================================================
--- electron/src/main/sidecar.ts	
+++ electron/src/main/sidecar.ts	
@@ -1,180 +1,191 @@
 // Spawns the Rust capture sidecar, parses its stdout for the `sidecar_ready`
 // announcement, then opens a WebSocket to it and relays events.

 import { spawn, ChildProcess } from "node:child_process";
 import { app } from "electron";
 import path from "node:path";
 import fs from "node:fs";
 import readline from "node:readline";
 import { EventEmitter } from "node:events";
 import WebSocket from "ws";

 import type { CaptureEvent, CaptureStatus } from "@shared/types";

 const HOST_ALLOWLIST = [
+  // OpenAI
   "api.openai.com",
-  "api.anthropic.com",
   "chat.openai.com",
+  "auth.openai.com",
+  // Anthropic
+  "api.anthropic.com",
   "claude.ai",
-  "api.cursor.sh",
+  // Google Gemini
   "generativelanguage.googleapis.com",
+  // xAI
   "api.x.ai",
+  // Cursor
+  "api.cursor.sh",
+  // OpenCode (gateway for `opencode/*` models + app auth)
+  "api.opencode.ai",
+  "app.opencode.ai",
+  // OpenRouter — frequently used by CLIs as a multi-provider gateway
+  "openrouter.ai",
 ];

 export interface SidecarEvents {
   event: (ev: CaptureEvent) => void;
   status: (status: CaptureStatus) => void;
 }

 export class Sidecar extends EventEmitter {
   private child: ChildProcess | null = null;
   private ws: WebSocket | null = null;
   private status: CaptureStatus = {
     sidecarRunning: false,
     proxyPort: null,
     wsPort: null,
     caCertPath: null,
     caFingerprintSha256: null,
     lastError: null,
   };

   getStatus(): CaptureStatus {
     return { ...this.status };
   }

   start(): void {
     if (this.child) return;

     const bin = resolveBinary();
     if (!bin) {
       this.updateStatus({
         lastError: "capture sidecar binary not found — run `pnpm build:sidecar`",
       });
       return;
     }

     const dataDir = path.join(app.getPath("userData"), "capture");
     fs.mkdirSync(dataDir, { recursive: true });

     const env = {
       ...process.env,
       REFLEX_DATA_DIR: dataDir,
       REFLEX_ALLOW_HOSTS: HOST_ALLOWLIST.join(","),
       REFLEX_LOG: process.env.REFLEX_LOG ?? "info",
     };

     const args = ["--proxy-port", "8888", "--ws-port", "0"];

     console.log(`[sidecar] spawning ${bin} ${args.join(" ")}`);
     const child = spawn(bin, args, { env, stdio: ["ignore", "pipe", "pipe"] });
     this.child = child;

     // stderr is free-form tracing logs — just forward to stdout.
     child.stderr?.on("data", (chunk) =>
       process.stderr.write(`[sidecar] ${chunk}`),
     );

     // stdout carries the `sidecar_ready` JSON line (and only that line today).
     const rl = readline.createInterface({ input: child.stdout! });
     rl.on("line", (line) => this.onSidecarStdout(line));

     child.once("exit", (code, signal) => {
       console.warn(`[sidecar] exited code=${code} signal=${signal}`);
       this.child = null;
       this.ws?.close();
       this.ws = null;
       this.updateStatus({ sidecarRunning: false });
     });

     child.once("error", (err) => {
       this.updateStatus({ lastError: err.message, sidecarRunning: false });
     });
   }

   stop(): void {
     this.ws?.close();
     this.ws = null;
     if (this.child && !this.child.killed) {
       this.child.kill("SIGTERM");
     }
     this.child = null;
     this.updateStatus({ sidecarRunning: false });
   }

   private onSidecarStdout(line: string): void {
     const trimmed = line.trim();
     if (!trimmed) return;
     let ev: CaptureEvent;
     try {
       ev = JSON.parse(trimmed);
     } catch (err) {
       console.warn("[sidecar] non-JSON stdout line:", trimmed);
       return;
     }
     if (ev.type === "sidecar_ready") {
       this.updateStatus({
         sidecarRunning: true,
         proxyPort: ev.proxy_port,
         wsPort: ev.ws_port,
         caCertPath: ev.ca_cert_path,
         caFingerprintSha256: ev.ca_fingerprint_sha256,
         lastError: null,
       });
       this.connectWs(ev.ws_port);
     }
   }

   private connectWs(port: number): void {
     const url = `ws://127.0.0.1:${port}`;
     console.log(`[sidecar] connecting WS → ${url}`);
     const ws = new WebSocket(url);
     this.ws = ws;

     ws.on("open", () => console.log("[sidecar] WS open"));
     ws.on("close", () => {
       console.log("[sidecar] WS close");
       this.ws = null;
     });
     ws.on("error", (err) => {
       console.warn("[sidecar] WS error:", err.message);
       this.updateStatus({ lastError: err.message });
     });
     ws.on("message", (data) => {
       const text = data.toString("utf8");
       let ev: CaptureEvent;
       try {
         ev = JSON.parse(text);
       } catch {
         return;
       }
       this.emit("event", ev);
     });
   }

   private updateStatus(patch: Partial<CaptureStatus>): void {
     this.status = { ...this.status, ...patch };
     this.emit("status", this.getStatus());
   }
 }

 function resolveBinary(): string | null {
   // 1. Packaged: out/main/../resources/capture (extraResources)
   // 2. Dev: electron/resources/capture (produced by scripts/build-sidecar.sh)
   // 3. Dev fallback: ../rust/target/debug/reflex-capture
   const candidates = [
     app.isPackaged
       ? path.join(process.resourcesPath, "capture")
       : path.join(app.getAppPath(), "resources", "capture"),
     path.join(app.getAppPath(), "..", "rust", "target", "release", "reflex-capture"),
     path.join(app.getAppPath(), "..", "rust", "target", "debug", "reflex-capture"),
   ];
   for (const c of candidates) {
     try {
       fs.accessSync(c, fs.constants.X_OK);
       return c;
     } catch {
       // continue
     }
   }
   return null;
 }

Index: scripts/tail-events.js
===================================================================
--- scripts/tail-events.js	
+++ scripts/tail-events.js	
@@ -0,0 +1,103 @@
+#!/usr/bin/env node
+/**
+ * Reflex event tail — connects to ws://127.0.0.1:<port> and prints a
+ * compact summary for each capture event. Used for manual smoke testing.
+ *
+ *   node scripts/tail-events.js --ws 9999 [--body]
+ *
+ * With --body the tool also prints decoded request/response bodies
+ * (truncated to 2KB per side).
+ */
+
+const path = require("node:path");
+const wsPath = path.join(
+  __dirname,
+  "..",
+  "electron",
+  "node_modules",
+  "ws",
+);
+const WebSocket = require(wsPath);
+
+const args = Object.fromEntries(
+  process.argv.slice(2).reduce((acc, arg, i, arr) => {
+    if (arg.startsWith("--") && arr[i + 1] && !arr[i + 1].startsWith("--")) {
+      acc.push([arg.slice(2), arr[i + 1]]);
+    } else if (arg.startsWith("--")) {
+      acc.push([arg.slice(2), "true"]);
+    }
+    return acc;
+  }, []),
+);
+const port = args.ws ?? "9999";
+const showBody = args.body === "true";
+
+const url = `ws://127.0.0.1:${port}`;
+const ws = new WebSocket(url);
+
+ws.on("open", () => console.error(`[tail] connected ${url}`));
+ws.on("error", (e) => console.error("[tail] error:", e.message));
+ws.on("close", () => {
+  console.error("[tail] closed");
+  process.exit(0);
+});
+
+const starts = new Map();
+
+ws.on("message", (buf) => {
+  const ev = JSON.parse(buf.toString("utf8"));
+  const t = new Date().toISOString().slice(11, 23);
+  switch (ev.type) {
+    case "sidecar_ready":
+      console.log(`${t} ready proxy=${ev.proxy_port} ws=${ev.ws_port}`);
+      break;
+    case "flow_start":
+      starts.set(ev.id, Date.now());
+      console.log(
+        `${t} ▶ ${ev.method.padEnd(4)} ${ev.scheme}://${ev.host}${ev.path}`,
+      );
+      break;
+    case "request_head":
+      if (showBody) {
+        const ct = ev.headers["content-type"] ?? "";
+        if (ct) console.log(`${t}   req content-type: ${ct}`);
+      }
+      break;
+    case "request_body":
+      if (showBody && ev.byte_len > 0) {
+        const body = Buffer.from(ev.body_b64, "base64").toString("utf8");
+        console.log(
+          `${t}   req body (${ev.byte_len}B${ev.truncated ? ", truncated" : ""}):`,
+        );
+        console.log(indent(clip(body, 2048)));
+      }
+      break;
+    case "response_head":
+      console.log(`${t}   ← status ${ev.status} http=${ev.http_version}`);
+      break;
+    case "response_body":
+      if (showBody && ev.byte_len > 0) {
+        const body = Buffer.from(ev.body_b64, "base64").toString("utf8");
+        console.log(
+          `${t}   resp body (${ev.byte_len}B${ev.truncated ? ", truncated" : ""}):`,
+        );
+        console.log(indent(clip(body, 2048)));
+      }
+      break;
+    case "flow_end":
+      console.log(
+        `${t} ✓ done in ${ev.duration_ms}ms${ev.error ? " err=" + ev.error : ""}`,
+      );
+      break;
+  }
+});
+
+function clip(s, n) {
+  return s.length > n ? s.slice(0, n) + `… (+${s.length - n}B)` : s;
+}
+function indent(s) {
+  return s
+    .split("\n")
+    .map((l) => "      " + l)
+    .join("\n");
+}

