  ipcMain.handle("reflex:list-flows", (_e, limit?: number) =>
    listFlows(limit ?? 200),
  );
  ipcMain.handle("reflex:get-flow", (_e, id: string) => getFlow(id));
  ipcMain.handle("reflex:status", () => sidecar.getStatus());
