import type { SessionSummary } from "../../../shared/types";

interface Props {
  sessions: SessionSummary[];
  selectedId: string | null;
  onSelect: (id: string) => void;
}

export function SessionList({
  sessions,
  selectedId,
  onSelect,
}: Props): JSX.Element {
  if (sessions.length === 0) {
    return (
      <div className="p-6 text-slate-500">
        No sessions yet. Run any AI CLI (opencode, claude, codex) with Reflex
        running — turns will appear here automatically.
      </div>
    );
  }

  return (
    <ul className="divide-y divide-slate-800">
      {sessions.map((s) => (
        <li key={`${s.source}:${s.session_id}`}>
          <button
            onClick={() => onSelect(s.session_id)}
            className={`flex w-full flex-col gap-0.5 px-3 py-2 text-left transition hover:bg-slate-900 ${
              selectedId === s.session_id ? "bg-slate-900" : ""
            }`}
          >
            <div className="flex items-center gap-2 text-xs">
              <SourceBadge source={s.source} />
              <span className="truncate text-slate-300">
                {s.first_user_text ?? s.session_id.slice(0, 24)}
              </span>
              <span className="ml-auto shrink-0 tabular-nums text-slate-500">
                {s.entry_count}
              </span>
            </div>
            <div className="flex items-center gap-2 truncate text-xs text-slate-500">
              <span>{formatTs(s.last_ts)}</span>
              {s.model && <span>· {s.model}</span>}
              {s.project && (
                <span className="truncate" title={s.project}>
                  · {basename(s.project)}
                </span>
              )}
            </div>
          </button>
        </li>
      ))}
    </ul>
  );
}

function SourceBadge({ source }: { source: string }): JSX.Element {
  const map: Record<string, string> = {
    opencode: "bg-sky-950 text-sky-300",
    "claude-code": "bg-amber-950 text-amber-300",
    codex: "bg-fuchsia-950 text-fuchsia-300",
  };
  const color = map[source] ?? "bg-slate-800 text-slate-300";
  return (
    <span
      className={`inline-block rounded px-1.5 text-[10px] font-medium uppercase tracking-wide ${color}`}
    >
      {source}
    </span>
  );
}

function formatTs(ts: string): string {
  try {
    const d = new Date(ts);
    const now = new Date();
    const sameDay =
      d.getFullYear() === now.getFullYear() &&
      d.getMonth() === now.getMonth() &&
      d.getDate() === now.getDate();
    if (sameDay)
      return d.toLocaleTimeString(undefined, {
        hour: "2-digit",
        minute: "2-digit",
      });
    return d.toLocaleDateString(undefined, {
      month: "short",
      day: "numeric",
    });
  } catch {
    return ts;
  }
}

function basename(p: string): string {
  const parts = p.split("/").filter(Boolean);
  return parts[parts.length - 1] ?? p;
}

import { useMemo, useState } from "react";

import type { SessionDetail, SessionEntry } from "../../../shared/types";

interface Props {
  session: SessionDetail | null;
}

export function SessionView({ session }: Props): JSX.Element {
  const [hideHousekeeping, setHideHousekeeping] = useState(true);

  if (!session) {
    return (
      <div className="flex h-full items-center justify-center text-slate-600">
        Select a session on the left
      </div>
    );
  }

  const entries = useMemo(() => {
    if (!hideHousekeeping) return session.entries;
    return session.entries.filter(
      (e) =>
        e.kind !== "system" &&
        e.kind !== "step-start" &&
        e.kind !== "step-finish" &&
        !e.kind.startsWith("event:") &&
        !(e.kind === "message" && !e.content),
    );
  }, [session.entries, hideHousekeeping]);

  return (
    <div className="flex h-full min-h-0 flex-col">
      <header className="shrink-0 border-b border-slate-800 p-4">
        <div className="flex items-baseline gap-2">
          <SourcePill source={session.source} />
          <span className="truncate text-slate-200 selectable">
            {session.first_user_text ?? session.session_id}
          </span>
        </div>
        <div className="mt-1 flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-slate-500">
          <span>id {session.session_id.slice(0, 16)}…</span>
          <span>·</span>
          <span>{session.entry_count} entries</span>
          {session.model && (
            <>
              <span>·</span>
              <span>{session.model}</span>
            </>
          )}
          {session.project && (
            <>
              <span>·</span>
              <span className="selectable truncate" title={session.project}>
                {session.project}
              </span>
            </>
          )}
          <span className="ml-auto">
            {formatRange(session.first_ts, session.last_ts)}
          </span>
        </div>
        <div className="mt-2 flex items-center gap-3 text-xs text-slate-400">
          <label className="flex items-center gap-1.5 cursor-pointer">
            <input
              type="checkbox"
              checked={hideHousekeeping}
              onChange={(e) => setHideHousekeeping(e.target.checked)}
              className="accent-sky-500"
            />
            hide housekeeping
          </label>
        </div>
      </header>

      <div className="min-h-0 flex-1 overflow-y-auto">
        <ol className="divide-y divide-slate-900">
          {entries.map((e) => (
            <li key={e.id}>
              <EntryRow entry={e} />
            </li>
          ))}
          {entries.length === 0 && (
            <li className="p-6 text-center text-slate-600">
              (no visible entries — toggle hide housekeeping off to see raw
              events)
            </li>
          )}
        </ol>
      </div>
    </div>
  );
}

function EntryRow({ entry }: { entry: SessionEntry }): JSX.Element {
  const [expanded, setExpanded] = useState(entry.content.length < 1200);

  const headerColor =
    entry.role === "user"
      ? "text-sky-300"
      : entry.role === "assistant"
        ? "text-emerald-300"
        : entry.role === "tool" || entry.kind === "tool_result"
          ? "text-amber-300"
          : entry.kind === "reasoning"
            ? "text-fuchsia-300"
            : entry.kind.startsWith("tool_call:")
              ? "text-cyan-300"
              : "text-slate-400";

  const label = entry.kind.startsWith("tool_call:")
    ? entry.kind
    : entry.kind === "reasoning"
      ? "reasoning"
      : entry.kind === "tool_result"
        ? "tool_result"
        : entry.role ?? entry.kind;

  const preview = collapseWhitespace(entry.content).slice(0, 160);

  return (
    <div className="px-4 py-2.5">
      <div className="flex items-baseline gap-2 text-xs">
        <span className={`font-semibold uppercase tracking-wide ${headerColor}`}>
          {label}
        </span>
        {entry.model && (
          <span className="text-slate-500">{entry.model}</span>
        )}
        <span className="ml-auto shrink-0 tabular-nums text-slate-600">
          {formatTime(entry.ts)}
        </span>
      </div>
      {entry.content && (
        <div className="mt-1.5">
          {expanded ? (
            <pre className="selectable whitespace-pre-wrap break-words text-xs leading-relaxed text-slate-300">
              {entry.content}
            </pre>
          ) : (
            <button
              onClick={() => setExpanded(true)}
              className="text-xs text-slate-400 hover:text-slate-200"
            >
              {preview}
              {entry.content.length > preview.length && (
                <span className="ml-1 text-sky-400">
                  [+{entry.byte_len - preview.length}B]
                </span>
              )}
            </button>
          )}
          {expanded && entry.content.length > 1200 && (
            <button
              onClick={() => setExpanded(false)}
              className="mt-1 text-[10px] text-slate-500 hover:text-slate-300"
            >
              collapse
            </button>
          )}
        </div>
      )}
    </div>
  );
