input.content:
// Canonical cross-source turn model — the unit the memory/rating layer
// operates on. Any source (opencode, claude-code, codex, network flows)
// normalizes into `Turn[]` so downstream code never has to know the
// origin format.

export type TurnRole = "user" | "assistant" | "tool" | "system";
export type TurnKind =
  | "message"
  | "reasoning"
  | "tool_call"
  | "tool_result"
  | "error";

export interface TurnTokens {
  input?: number;
  output?: number;
  cached?: number;
}

export interface TurnTool {
  name: string;
  /** Arguments passed to the tool (parsed when possible). */
  args?: unknown;
  /** Output returned by the tool, if any. */
  output?: string;
  /** Whether the tool call resulted in an error. */
  errored?: boolean;
  /** Error message extracted from tool output / downstream turns. */
  error?: string;
}

export interface Turn {
  // Identity
  session_id: string;
  source: string;          // "opencode" | "claude-code" | "codex" | "network:<host>"
  source_entry_id: string; // stable id inside the source
  source_parent_id?: string | null;

  // Normalized content
  ts: string;                // RFC3339
  role: TurnRole;
  kind: TurnKind;
  text: string;              // primary content (may be empty)
  model?: string | null;
  tool?: TurnTool;           // when kind = tool_call | tool_result
  tokens?: TurnTokens;
  latency_ms?: number;

  // Metadata
  truncated?: boolean;
  byte_len?: number;
  raw_kind?: string;         // original source-native kind (for debugging)
}

// ---------- Rating types -------------------------------------------------

export interface Mistake {
  /** Index into the session's `Turn[]`. */
  at_turn_index: number;
  tool_name: string;
  /** JSON-serialized args (truncated). */
  args_preview: string;
  error: string;
  /** Index of the turn that fixed it, if we can identify one. */
  resolved_at?: number;
}

export interface RetryCluster {
  tool_name: string;
  /** Turn indices of each retry in order. */
  indices: number[];
  /** Whether the final call succeeded. */
  resolved: boolean;
  /** Short summary of what changed between retries. */
  delta?: string;
}

export interface Correction {
  at_turn_index: number;
  /** The user's correction text (trimmed). */
  phrase: string;
  /** Optional inferred target of the correction. */
  target?: string;
}

export interface Reversal {
  at_turn_index: number;
  file_path: string;
  /** Short description of the change-and-revert. */
  description: string;
}

export interface SessionRating {
  session_id: string;
  source: string;
  /** 0..100 where 100 = flawless, 0 = ruinous. */
  score: number;
  evaluated_at: string;

  // Signal breakdowns
  mistakes: Mistake[];
  retries: RetryCluster[];
  corrections: Correction[];
  reversals: Reversal[];

  // Aggregates
  turn_count: number;
  tool_call_count: number;
  tool_error_count: number;
  user_turn_count: number;
  assistant_turn_count: number;
  wall_time_ms: number;
  /** Per-model token accounting when available. */
  tokens_by_model: Record<string, TurnTokens>;
}

// Normalize heterogeneous session_entries rows → canonical Turn[].
//
// Each source has its own quirks. The rules here encode only *structural*
// knowledge of each source; downstream code (rating, UI threading) never
// has to reference source-specific shapes.

import type { SessionEntry } from "@shared/types";
import type { Turn, TurnKind, TurnRole, TurnTool, TurnTokens } from "@shared/turn";

/**
 * Convert a bag of captured entries for a single session into a canonical
 * list of Turn objects, in chronological order.
 *
 * Callers usually pass one session's entries at a time so adjacency signals
 * (tool_call → tool_result linking, retry clusters) behave correctly.
 */
export function normalizeEntries(entries: SessionEntry[]): Turn[] {
  // Sort by ts then insertion id to stabilize.
  const ordered = [...entries].sort((a, b) => {
    const cmp = a.ts.localeCompare(b.ts);
    return cmp !== 0 ? cmp : a.id.localeCompare(b.id);
  });

  const turns: Turn[] = [];
  // For opencode: track the most recent message row so subsequent parts can
  // inherit its role/model (opencode splits them across tables).
  let lastOpencodeMsgHeader: {
    role: TurnRole;
    model?: string | null;
    entry_id: string;
  } | null = null;

  for (const e of ordered) {
    if (e.source === "opencode") {
      // The message rows from opencode carry role/model but empty content.
      // We don't emit them; their role/model is inherited by subsequent
      // parts that reference them via parent_entry_id.
      if (e.kind === "message" && !e.content && e.role) {
        lastOpencodeMsgHeader = {
          role: e.role as TurnRole,
          model: e.model,
          entry_id: e.entry_id,
        };
        continue;
      }

      // Skip pure step markers — they're progress noise.
      if (e.kind === "step-start" || e.kind === "step-finish") continue;

      const inherited = lastOpencodeMsgHeader;

      if (e.kind === "message") {
        turns.push(mkMessage(e, inherited?.role ?? "assistant", inherited?.model));
      } else if (e.kind === "reasoning") {
        turns.push(mkReasoning(e, inherited?.model));
      } else if (e.kind.startsWith("tool_call:")) {
        turns.push(mkToolCall(e, inherited?.model));
      } else if (e.kind === "patch") {
        // Patches are artifacts of tool calls; surface as tool_result.
        turns.push(mkToolResult(e, "patch"));
      }
      continue;
    }

    if (e.source === "claude-code") {
      if (e.kind === "system") continue; // housekeeping

      if (e.kind === "message") {
        turns.push(mkMessage(e, (e.role ?? "assistant") as TurnRole, e.model));
      } else if (e.kind === "reasoning") {
        turns.push(mkReasoning(e, e.model));
      } else if (e.kind.startsWith("tool_call:")) {
        turns.push(mkToolCall(e, e.model));
      } else if (e.kind === "tool_result") {
        turns.push(mkToolResult(e, null));
      }
      continue;
    }

    if (e.source === "codex") {
      if (e.kind.startsWith("event:")) continue; // task_started / task_completed noise

      if (e.kind === "message") {
        turns.push(mkMessage(e, (e.role ?? "assistant") as TurnRole, e.model));
      } else if (e.kind === "reasoning") {
        turns.push(mkReasoning(e, e.model));
      } else if (e.kind.startsWith("tool_call:")) {
        turns.push(mkToolCall(e, e.model));
      } else if (e.kind === "tool_result") {
        turns.push(mkToolResult(e, null));
      }
      continue;
    }

    // Unknown source — pass through as a best-guess message turn.
    turns.push(mkMessage(e, (e.role ?? "system") as TurnRole, e.model));
  }

  // Second pass: link tool_result turns to their originating tool_call so
  // the rating engine can see errors. Heuristic: nearest preceding
  // tool_call of matching name in the same session.
  linkToolResults(turns);

  return turns;
}

// ---------- Builders ---------------------------------------------------

function mkMessage(
  e: SessionEntry,
  role: TurnRole,
  model: string | null | undefined,
): Turn {
  return base(e, "message", role, model);
}

function mkReasoning(e: SessionEntry, model: string | null | undefined): Turn {
  return base(e, "reasoning", "assistant", model);
}

function mkToolCall(e: SessionEntry, model: string | null | undefined): Turn {
  const toolName = e.kind.slice("tool_call:".length);
  let args: unknown = undefined;
  try {
    args = e.content ? JSON.parse(e.content) : undefined;
  } catch {
    args = e.content; // pass string as-is
  }
  const t = base(e, "tool_call", "assistant", model);
  t.tool = { name: toolName, args };
  return t;
}

function mkToolResult(e: SessionEntry, fallbackTool: string | null): Turn {
  const t = base(e, "tool_result", "tool", null);
  const name =
    (e.metadata as Record<string, unknown> | undefined)?.["tool"] &&
    typeof (e.metadata as Record<string, unknown>)["tool"] === "string"
      ? ((e.metadata as Record<string, unknown>)["tool"] as string)
      : fallbackTool ?? "unknown";
  const errored = detectError(e.content);
  t.tool = {
    name,
    output: e.content,
    errored,
    error: errored ? extractErrorLine(e.content) : undefined,
  };
  return t;
}

function base(
  e: SessionEntry,
  kind: TurnKind,
  role: TurnRole,
  model: string | null | undefined,
): Turn {
  return {
    session_id: e.session_id,
    source: e.source,
    source_entry_id: e.entry_id,
    source_parent_id: e.parent_entry_id ?? null,
    ts: e.ts,
    role,
    kind,
    text: e.content,
    model: model ?? null,
    byte_len: e.byte_len,
    raw_kind: e.kind,
  };
}

// ---------- Tool linking -----------------------------------------------

function linkToolResults(turns: Turn[]): void {
  for (let i = 0; i < turns.length; i++) {
    const t = turns[i];
    if (t.kind !== "tool_result") continue;
    const name = t.tool?.name;
    if (!name || name === "unknown") continue;

    // Walk back to find the most recent matching tool_call without a result.
    for (let j = i - 1; j >= 0; j--) {
      const c = turns[j];
      if (
        c.kind === "tool_call" &&
        c.tool?.name === name &&
        !(c.tool as TurnTool & { _linked?: boolean })._linked
      ) {
        const tool = c.tool!;
        (tool as TurnTool & { _linked?: boolean })._linked = true;
        c.tool = {
          ...tool,
          output: t.tool?.output ?? tool.output,
          errored: t.tool?.errored ?? tool.errored,
          error: t.tool?.error ?? tool.error,
        };
        break;
      }
    }
  }
}

// ---------- Error heuristics ------------------------------------------

/**
 * Cheap detector for "this tool output looks like an error". Intentionally
 * high-recall; the rating layer trims down.
 */
function detectError(output: string): boolean {
  if (!output) return false;
  const head = output.slice(0, 2048).toLowerCase();
  if (/(^|\W)(error|exception|traceback|stack ?trace|fatal):/i.test(head))
    return true;
  if (/panic!/i.test(head)) return true;
  if (/command ?not ?found/i.test(head)) return true;
  if (/permission denied/i.test(head)) return true;
  if (/no such file or directory/i.test(head)) return true;
  if (/\berror\s*:/i.test(head) && /(line|at )\b/i.test(head)) return true;
  if (/exit(ed)? (code|status)\s*[:=]?\s*[1-9]/i.test(head)) return true;
  if (/failed (with|to)/i.test(head) && head.includes("error")) return true;
  return false;
}

function extractErrorLine(output: string): string {
  const head = output.slice(0, 4096);
  // Prefer the first line containing "error" / "failed" / "exception".
  for (const ln of head.split(/\r?\n/)) {
    if (/(error|failed|exception|traceback|panic)/i.test(ln) && ln.trim().length) {
      return ln.trim().slice(0, 300);
    }
  }
  return head.split(/\r?\n/)[0]?.slice(0, 300) ?? "";
}

/** Public helper — useful in tests / debug. */
export function isErrorText(s: string): boolean {
  return detectError(s);
}

/** Helper: rough token estimate when a source didn't record tokens. */
export function estimateTokens(text: string): TurnTokens {
  return { input: Math.ceil(text.length / 4) };
}

// Rate a single session's Turn[] — produce mistakes, retries, corrections,
// reversals, and an aggregate 0..100 score.
//
// Heuristic-driven, transparent, small. The goal is to produce actionable
// signals an agent can read on startup ("you tried `rg -U` and it failed
// three times; use a different approach"), not to be a clever ML model.

import type {
  Correction,
  Mistake,
  RetryCluster,
  Reversal,
  SessionRating,
  Turn,
  TurnTokens,
} from "@shared/turn";

export function rateSession(turns: Turn[]): SessionRating | null {
  if (turns.length === 0) return null;

  const first = turns[0];
  const session_id = first.session_id;
  const source = first.source;

  // Aggregates
  const user_turns = turns.filter((t) => t.role === "user" && t.kind === "message");
  const assistant_turns = turns.filter(
    (t) => t.role === "assistant" && t.kind === "message",
  );
  const tool_calls = turns.filter((t) => t.kind === "tool_call");
  const tool_errors = tool_calls.filter((t) => t.tool?.errored);

  const mistakes = detectMistakes(turns);
  const retries = detectRetries(turns);
  const corrections = detectCorrections(turns);
  const reversals = detectReversals(turns);

  const tokens_by_model = aggregateTokens(turns);
  const wall_time_ms = wallTime(turns);

  const score = computeScore({
    turnCount: turns.length,
    toolCallCount: tool_calls.length,
    toolErrorCount: tool_errors.length,
    retryCount: retries.length,
    correctionCount: corrections.length,
    reversalCount: reversals.length,
    unresolvedMistakes: mistakes.filter((m) => m.resolved_at === undefined).length,
  });

  return {
    session_id,
    source,
    score,
    evaluated_at: new Date().toISOString(),
    mistakes,
    retries,
    corrections,
    reversals,
    turn_count: turns.length,
    tool_call_count: tool_calls.length,
    tool_error_count: tool_errors.length,
    user_turn_count: user_turns.length,
    assistant_turn_count: assistant_turns.length,
    wall_time_ms,
    tokens_by_model,
  };
}

// ---------- Detectors --------------------------------------------------

function detectMistakes(turns: Turn[]): Mistake[] {
  const out: Mistake[] = [];
  for (let i = 0; i < turns.length; i++) {
    const t = turns[i];
    if (t.kind !== "tool_call" || !t.tool?.errored) continue;
    const name = t.tool.name;
    const args_preview = serializeArgs(t.tool.args);
    const err = t.tool.error ?? "(unknown error)";

    // Look forward for a resolver: the next successful same-tool call
    // whose args look materially different, OR an explicit "fixed" phrase.
    let resolved_at: number | undefined;
    for (let j = i + 1; j < turns.length; j++) {
      const u = turns[j];
      if (
        u.kind === "tool_call" &&
        u.tool?.name === name &&
        !u.tool.errored &&
        serializeArgs(u.tool.args) !== args_preview
      ) {
        resolved_at = j;
        break;
      }
      if (
        u.kind === "message" &&
        u.role === "assistant" &&
        /(\bfixed\b|now works|resolved|got it working)/i.test(u.text)
      ) {
        resolved_at = j;
        break;
      }
    }

    out.push({
      at_turn_index: i,
      tool_name: name,
      args_preview,
      error: err.slice(0, 400),
      resolved_at,
    });
  }
  return out;
}

function detectRetries(turns: Turn[]): RetryCluster[] {
  const clusters: RetryCluster[] = [];
  const seen = new Set<number>();

  for (let i = 0; i < turns.length; i++) {
    if (seen.has(i)) continue;
    const a = turns[i];
    if (a.kind !== "tool_call") continue;
    const name = a.tool?.name;
    if (!name) continue;

    // Look for rapid-fire same-tool calls after a.
    const indices: number[] = [i];
    for (let j = i + 1; j < turns.length && j < i + 10; j++) {
      const b = turns[j];
      // Allow intervening tool_result / reasoning turns
      if (b.kind === "tool_call") {
        if (b.tool?.name === name) {
          indices.push(j);
        } else {
          break; // different tool → new chain
        }
      } else if (
        b.kind === "message" &&
        b.role === "user"
      ) {
        break; // user re-entered
      }
    }
    if (indices.length >= 2) {
      for (const k of indices) seen.add(k);
      const last = turns[indices[indices.length - 1]];
      clusters.push({
        tool_name: name,
        indices,
        resolved: !(last.tool?.errored ?? false),
        delta: describeDelta(
          turns[indices[0]].tool?.args,
          turns[indices[indices.length - 1]].tool?.args,
        ),
      });
    }
  }
  return clusters;
}

const CORRECTION_PATTERNS = [
  /^(no|nope|nah)[,.\s!?]/i,
  /^(wait|hold on|stop)[,.\s!?]/i,
  /that('s| is) (wrong|not right|incorrect)/i,
  /(actually[,.\s]|instead[,.\s]|please )/i,
  /(don'?t|do not) (do|use|run)/i,
  /try (again|different|another)/i,
  /(not what i|that isn'?t what)/i,
  /undo that/i,
  /revert/i,
];

function detectCorrections(turns: Turn[]): Correction[] {
  const out: Correction[] = [];
  for (let i = 0; i < turns.length; i++) {
    const t = turns[i];
    if (t.role !== "user" || t.kind !== "message") continue;
    const text = t.text.trim();
    if (text.length < 3) continue;
    const head = text.slice(0, 400);
    for (const pat of CORRECTION_PATTERNS) {
      if (pat.test(head)) {
        out.push({
          at_turn_index: i,
          phrase: head.slice(0, 200),
        });
        break;
      }
    }
  }
  return out;
}

/**
 * A reversal = assistant writes/edits a file, then later writes/edits the
 * same file to undo / substantially change the earlier work.
 *
 * Heuristic: track file_path args across Write/Edit tool_calls; if the
 * same path appears twice with the second call's args materially shorter
 * or containing "revert" / "undo" in surrounding context, flag it.
 */
function detectReversals(turns: Turn[]): Reversal[] {
  const seenPaths = new Map<string, number[]>();
  for (let i = 0; i < turns.length; i++) {
    const t = turns[i];
    if (t.kind !== "tool_call") continue;
    const nm = t.tool?.name?.toLowerCase() ?? "";
    if (!["write", "edit", "str_replace", "multiedit"].some((x) => nm.includes(x))) {
      continue;
    }
    const path = extractPath(t.tool?.args);
    if (!path) continue;
    const arr = seenPaths.get(path) ?? [];
    arr.push(i);
    seenPaths.set(path, arr);
  }

  const out: Reversal[] = [];
  for (const [path, indices] of seenPaths) {
    if (indices.length < 2) continue;
    const last = indices[indices.length - 1];
    // Naive description
    out.push({
      at_turn_index: last,
      file_path: path,
      description: `${indices.length} edits to ${path}`,
    });
  }
  return out;
}

// ---------- Scoring ----------------------------------------------------

function computeScore(x: {
  turnCount: number;
  toolCallCount: number;
  toolErrorCount: number;
  retryCount: number;
  correctionCount: number;
  reversalCount: number;
  unresolvedMistakes: number;
}): number {
  if (x.turnCount === 0) return 100;

  // Start at 100, subtract penalties.
  let s = 100;
  const errRate = x.toolCallCount ? x.toolErrorCount / x.toolCallCount : 0;
  s -= Math.min(30, errRate * 60);
  s -= Math.min(20, x.retryCount * 3);
  s -= Math.min(20, x.correctionCount * 4);
  s -= Math.min(15, x.reversalCount * 3);
  s -= Math.min(25, x.unresolvedMistakes * 5);
  return Math.max(0, Math.round(s));
}

// ---------- Helpers ----------------------------------------------------

function wallTime(turns: Turn[]): number {
  if (turns.length < 2) return 0;
  const first = new Date(turns[0].ts).getTime();
  const last = new Date(turns[turns.length - 1].ts).getTime();
  if (!isFinite(first) || !isFinite(last)) return 0;
  return Math.max(0, last - first);
}

function aggregateTokens(turns: Turn[]): Record<string, TurnTokens> {
  const by: Record<string, TurnTokens> = {};
  for (const t of turns) {
    if (!t.tokens) continue;
    const key = t.model ?? "unknown";
    const acc = by[key] ?? {};
    if (t.tokens.input) acc.input = (acc.input ?? 0) + t.tokens.input;
    if (t.tokens.output) acc.output = (acc.output ?? 0) + t.tokens.output;
    if (t.tokens.cached) acc.cached = (acc.cached ?? 0) + t.tokens.cached;
    by[key] = acc;
  }
  return by;
}

function serializeArgs(args: unknown): string {
  if (args === undefined || args === null) return "";
  try {
    const s = typeof args === "string" ? args : JSON.stringify(args);
    return s.length > 200 ? s.slice(0, 200) + "…" : s;
  } catch {
    return String(args);
  }
}

function describeDelta(a: unknown, b: unknown): string | undefined {
  if (a === undefined || b === undefined) return undefined;
  const A = serializeArgs(a);
  const B = serializeArgs(b);
  if (A === B) return "args identical";
  // Find common prefix length, then first divergent char.
  let i = 0;
  while (i < A.length && i < B.length && A[i] === B[i]) i++;
  return `diverged at char ${i}`;
}

function extractPath(args: unknown): string | null {
  if (!args || typeof args !== "object") return null;
  const o = args as Record<string, unknown>;
  for (const key of ["file_path", "filepath", "path", "filePath", "file"]) {
    const v = o[key];
    if (typeof v === "string" && v.length) return v;
  }
  return null;
}

