 }

 function Section({
   title,
   tone,
   children,
 }: {
   title: string;
   tone?: "amber" | "fuchsia" | "sky";
   children: React.ReactNode;
 }): JSX.Element {
   const tc =
     tone === "amber"
       ? "text-amber-300"
       : tone === "fuchsia"
         ? "text-fuchsia-300"
         : tone === "sky"
           ? "text-sky-300"
           : "text-slate-400";
