input.content:
// GitHub integration — opens a PR against a user's repo that updates their
// agent-context file (AGENTS.md / CLAUDE.md / etc.) with Reflex's distilled
// cross-session insight. Uses Octokit's Git Data API so no local `git`
// shellouts or clones are required — everything happens via HTTPS.
//
// Auth: user pastes a GitHub Personal Access Token (classic, `repo` scope)
// into ~/.reflex/config.json as `github_token`.

import fs from "node:fs";
import path from "node:path";

import { Octokit } from "@octokit/rest";

import type { RepoInsight } from "@shared/judge";
import { loadConfig } from "./config";

// Files we'll update (in priority order — first existing one wins).
// If none exist we create AGENTS.md at the repo root.
const CONTEXT_FILE_CANDIDATES = [
  "AGENTS.md",
  "CLAUDE.md",
  ".github/copilot-instructions.md",
  ".cursor/rules",
  "CODEX.md",
  "AGENT.md",
];

const REFLEX_BLOCK_START = "<!-- reflex:context:start -->";
const REFLEX_BLOCK_END = "<!-- reflex:context:end -->";

export interface GitHubRepoRef {
  owner: string;
  repo: string;
  /** Default branch name (e.g. "main"). */
  default_branch: string;
  /** https://github.com/<owner>/<repo> */
  html_url: string;
}

export interface OpenPrResult {
  pr_url: string;
  pr_number: number;
  branch: string;
  target_file: string;
  action: "created" | "updated" | "replaced-reflex-block";
}

/**
 * Detect a GitHub repo from a local directory by reading `.git/config`.
 * Supports HTTPS + SSH origin URLs. Does NOT require the path to be a git
 * repo — pure text parsing, so works when the directory is read-only.
 */
export function detectGitHubRemote(
  localPath: string,
): { owner: string; repo: string } | null {
  try {
    const cfgPath = path.join(localPath, ".git", "config");
    const body = fs.readFileSync(cfgPath, "utf8");
    // Find the [remote "origin"] section, then the first `url = ...` line within it.
    const m = body.match(/\[remote "origin"\][\s\S]*?url\s*=\s*([^\s]+)/);
    if (!m) return null;
    return parseGitHubRemoteUrl(m[1]);
  } catch {
    return null;
  }
}

export function parseGitHubRemoteUrl(
  url: string,
): { owner: string; repo: string } | null {
  // https://github.com/owner/repo.git
  let m = url.match(/github\.com[:/]{1}([^/]+)\/([^/\s]+?)(?:\.git)?$/);
  if (m) return { owner: m[1], repo: m[2] };
  // SSH short-form (handled by the one above, but for safety)
  m = url.match(/^git@github\.com:([^/]+)\/([^/\s]+?)(?:\.git)?$/);
  if (m) return { owner: m[1], repo: m[2] };
  return null;
}

function mustGitHub(): Octokit {
  const cfg = loadConfig();
  if (!cfg.github_token) {
    throw new Error(
      "no github_token in ~/.reflex/config.json — paste a classic PAT with `repo` scope",
    );
  }
  return new Octokit({
    auth: cfg.github_token,
    userAgent: "reflex-capture/0.1",
  });
}

/**
 * Open a PR in the given repo that patches the agent-context file with the
 * rendered body of a RepoInsight. Returns the PR URL.
 *
 * Strategy:
 *   1. Resolve owner/repo/default branch.
 *   2. Find existing context file (AGENTS.md, CLAUDE.md, …) — pick the first
 *      that exists.  If none, use AGENTS.md.
 *   3. Read current file content. If it contains a Reflex sentinel block,
 *      replace that block. Otherwise append a fresh Reflex block (file
 *      stays otherwise intact).
 *   4. Create a new branch off default_branch, push one commit, open a PR.
 */
export async function openPrForInsight(params: {
  localRepoPath: string;
  insight: RepoInsight;
}): Promise<OpenPrResult> {
  const { localRepoPath, insight } = params;

  const remote = detectGitHubRemote(localRepoPath);
  if (!remote) {
    throw new Error(
      `could not detect a GitHub origin in ${localRepoPath}/.git/config — is this a GitHub repo?`,
    );
  }
  const { owner, repo } = remote;
  const gh = mustGitHub();

  // 1. Default branch
  const repoInfo = await gh.repos.get({ owner, repo });
  const defaultBranch = repoInfo.data.default_branch;

  // 2. Find existing context file
  let target: string | null = null;
  let existingSha: string | undefined;
  let existingContent = "";
  for (const candidate of CONTEXT_FILE_CANDIDATES) {
    try {
      const res = await gh.repos.getContent({
        owner,
        repo,
        path: candidate,
        ref: defaultBranch,
      });
      const d = res.data as {
        sha?: string;
        encoding?: string;
        content?: string;
        type?: string;
      };
      if (d.type === "file") {
        target = candidate;
        existingSha = d.sha;
        if (d.content && d.encoding === "base64") {
          existingContent = Buffer.from(d.content, "base64").toString("utf8");
        }
        break;
      }
    } catch (e) {
      const err = e as { status?: number };
      if (err.status && err.status !== 404) {
        throw new Error(
          `unexpected error reading ${candidate}: ${(e as Error).message}`,
        );
      }
      // 404 → file doesn't exist, try next candidate
    }
  }

  if (!target) target = "AGENTS.md";

  // 3. Compose new body
  const { body: newBody, action } = mergeContextBlock(existingContent, insight);

  // 4. Create branch
  const branch = newBranchName(insight);
  const mainRef = await gh.git.getRef({
    owner,
    repo,
    ref: `heads/${defaultBranch}`,
  });
  const baseSha = mainRef.data.object.sha;

  try {
    await gh.git.createRef({
      owner,
      repo,
      ref: `refs/heads/${branch}`,
      sha: baseSha,
    });
  } catch (e) {
    const err = e as { status?: number; message?: string };
    if (err.status !== 422) throw e;
    // branch already exists (likely because user re-ran) — fine, we'll update it below
  }

  // 5. Commit via contents API (handles both create + update)
  const commitMsg = `chore(agents): refresh Reflex-derived context (${insight.session_count} sessions, avg ${insight.score_avg}/100)`;
  await gh.repos.createOrUpdateFileContents({
    owner,
    repo,
    path: target,
    branch,
    message: commitMsg,
    content: Buffer.from(newBody, "utf8").toString("base64"),
    sha: existingSha, // present → update, absent → create
    committer: {
      name: "Reflex",
      email: "reflex@localhost",
    },
    author: {
      name: "Reflex",
      email: "reflex@localhost",
    },
  });

  // 6. Open PR
  const prBody = buildPrBody(insight, action, target);
  const prTitle = `Refresh agent context from ${insight.session_count} Reflex-judged session${insight.session_count === 1 ? "" : "s"}`;

  let prUrl: string;
  let prNumber: number;

  try {
    const pr = await gh.pulls.create({
      owner,
      repo,
      head: branch,
      base: defaultBranch,
      title: prTitle,
      body: prBody,
      draft: false,
    });
    prUrl = pr.data.html_url;
    prNumber = pr.data.number;
  } catch (e) {
    const err = e as { status?: number };
    // 422 happens if a PR already exists on this branch
    if (err.status === 422) {
      const existing = await gh.pulls.list({
        owner,
        repo,
        head: `${owner}:${branch}`,
        state: "open",
      });
      if (existing.data.length === 0) throw e;
      prUrl = existing.data[0].html_url;
      prNumber = existing.data[0].number;
      // Update body + title to reflect the new analysis
      await gh.pulls.update({
        owner,
        repo,
        pull_number: prNumber,
        title: prTitle,
        body: prBody,
      });
    } else {
      throw e;
    }
  }

  return {
    pr_url: prUrl,
    pr_number: prNumber,
    branch,
    target_file: target,
    action,
  };
}

// ----- Body merging --------------------------------------------------------

function mergeContextBlock(
  existing: string,
  insight: RepoInsight,
): { body: string; action: OpenPrResult["action"] } {
  const block = renderReflexBlock(insight);

  if (!existing.trim()) {
    return { body: block.trimStart(), action: "created" };
  }

  // Replace an existing sentinel block if present.
  if (
    existing.includes(REFLEX_BLOCK_START) &&
    existing.includes(REFLEX_BLOCK_END)
  ) {
    const before = existing.slice(0, existing.indexOf(REFLEX_BLOCK_START));
    const afterIdx =
      existing.indexOf(REFLEX_BLOCK_END) + REFLEX_BLOCK_END.length;
    const after = existing.slice(afterIdx);
    const merged = before.replace(/\s+$/, "") + "\n\n" + block + after;
    return { body: merged, action: "replaced-reflex-block" };
  }

  // Otherwise append a fresh block at the end.
  const needsSpacer = !existing.endsWith("\n");
  const merged = existing + (needsSpacer ? "\n\n" : "\n") + block;
  return { body: merged, action: "updated" };
}

function renderReflexBlock(insight: RepoInsight): string {
  // Use the judge's own context_md verbatim, wrapped in sentinels so we
  // can find+replace on subsequent runs.
  const trimmedMd = insight.context_md.trim();
  const meta = [
    `> Refreshed ${new Date(insight.evaluated_at).toISOString().slice(0, 19)}Z`,
    `> Based on ${insight.session_count} Reflex-judged session${insight.session_count === 1 ? "" : "s"}, avg score ${insight.score_avg}/100`,
    `> Judge: ${insight.judge}`,
  ].join("\n");

  return [
    REFLEX_BLOCK_START,
    "",
    meta,
    "",
    trimmedMd,
    "",
    REFLEX_BLOCK_END,
    "",
  ].join("\n");
}

function buildPrBody(
  insight: RepoInsight,
  action: OpenPrResult["action"],
  target: string,
): string {
  const actionText = {
    created: `Created \`${target}\` with the initial Reflex-derived context block.`,
    updated: `Appended a Reflex-derived context block to \`${target}\`.`,
    "replaced-reflex-block": `Refreshed the existing Reflex block inside \`${target}\`.`,
  }[action];

  const lines: string[] = [
    `**Summary**: ${insight.summary}`,
    "",
    actionText,
    "",
    `This PR was opened by [Reflex](https://github.com/) after analyzing **${insight.session_count}** past AI-agent session(s) in this repo (average score **${insight.score_avg}/100**, evaluated with \`${insight.judge}\`).`,
    "",
  ];

  if (insight.recurring_agent_patterns.length) {
    lines.push(`### Recurring agent patterns (across sessions)`);
    for (const p of insight.recurring_agent_patterns.slice(0, 8)) {
      lines.push(`- ${p}`);
    }
    lines.push("");
  }

  if (insight.recurring_user_patterns.length) {
    lines.push(`### Recurring user patterns`);
    for (const p of insight.recurring_user_patterns.slice(0, 8)) {
      lines.push(`- ${p}`);
    }
    lines.push("");
  }

  if (insight.actionable_advice.length) {
    lines.push(`### Actionable advice baked into the context`);
    for (const a of insight.actionable_advice.slice(0, 10)) {
      lines.push(`- ${a}`);
    }
    lines.push("");
  }

  lines.push(
    "---",
    "<sub>The block between `<!-- reflex:context:start -->` and `<!-- reflex:context:end -->` will be refreshed in place on future PRs. Edit outside that block freely.</sub>",
  );
  return lines.join("\n");
}

function newBranchName(insight: RepoInsight): string {
  // Deterministic branch per repo so re-runs update the same PR.
  return "reflex/agent-context";
}

