 /** Detect GitHub owner/repo from a local directory's .git/config. */
 export function detectGitHubRemote(
   localPath: string,
 ): { owner: string; repo: string } | null {
   try {
     const cfgPath = path.join(localPath, ".git", "config");
     const body = fs.readFileSync(cfgPath, "utf8");
     const m = body.match(/\[remote "origin"\][\s\S]*?url\s*=\s*([^\s]+)/);
     if (!m) return null;
     return parseGitHubRemoteUrl(m[1]);
   } catch {
     return null;
   }
 }

 export function parseGitHubRemoteUrl(
   url: string,
 ): { owner: string; repo: string } | null {
   let m = url.match(/github\.com[:/]{1}([^/]+)\/([^/\s]+?)(?:\.git)?$/);
   if (m) return { owner: m[1], repo: m[2] };
   m = url.match(/^git@github\.com:([^/]+)\/([^/\s]+?)(?:\.git)?$/);
   if (m) return { owner: m[1], repo: m[2] };
   return null;
 }

 // ------------------------- REST helpers ------------------------------------

 function token(): string {
   const cfg = loadConfig();
   if (!cfg.github_token) {
     throw new Error(
       "no github_token in ~/.reflex/config.json — paste a classic PAT with `repo` scope",
     );
   }
   return cfg.github_token;
 }

 interface GhErr {
   status: number;
   url: string;
   message: string;
   body?: unknown;
 }

 async function gh<T = unknown>(
   method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE",
   url: string,
   body?: unknown,
 ): Promise<T> {
   const res = await fetch(`${GH}${url}`, {
     method,
     headers: {
       accept: "application/vnd.github+json",
       "x-github-api-version": "2022-11-28",
       authorization: `Bearer ${token()}`,
       "user-agent": UA,
       ...(body ? { "content-type": "application/json" } : {}),
     },
     body: body ? JSON.stringify(body) : undefined,
   });
   if (res.status === 204) return undefined as T;
   const payload = (await res.json().catch(() => ({}))) as Record<
     string,
     unknown
   >;
   if (!res.ok) {
     const err: GhErr = {
       status: res.status,
       url,
       message:
         (payload.message as string) ??
         `github ${method} ${url} failed: ${res.status} ${res.statusText}`,
       body: payload,
     };
     const e = new Error(err.message) as Error & GhErr;
     e.status = err.status;
     e.url = err.url;
     e.body = err.body;
     throw e;
   }
   return payload as T;
