     const onBranch = await gh<{ sha: string }>(
       "GET",
       `/repos/${owner}/${repo}/contents/${encodeURIComponent(target)}?ref=${encodeURIComponent(branch)}`,
     );
     branchFileSha = onBranch.sha;
   } catch (e) {
     const err = e as GhErr;
     if (err.status !== 404) throw e;
