   }

   registerIpc();
   wireSidecar();
   sidecar.start();
   createWindow();

   // Warm up ratings for existing sessions on first launch (cheap; runs
   // off the event loop).
   queueMicrotask(() => {
     try {
       const n = computeRatingsForAllSessions();
       if (n > 0) console.log(`[reflex] warmed ratings for ${n} sessions`);
