+                  <span className="ml-auto shrink-0 text-slate-600">
+                    {formatTs(pr.updated_at)} · {pr.author_login ?? "?"}
+                  </span>
+                </li>
+              ))}
+            </ul>
+          )}
+        </div>
+      </div>
