+  if (diffH < 24) return `${Math.round(diffH)}h ago`;
+  if (diffH < 24 * 7) return `${Math.round(diffH / 24)}d ago`;
+  return d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
