 function formatTime(ts: string): string {
   try {
     const d = new Date(ts);
     return d.toLocaleTimeString(undefined, {
       hour: "2-digit",
       minute: "2-digit",
       second: "2-digit",
     });
   } catch {
     return ts;
   }
 }

 function formatRange(first: string, last: string): string {
   try {
     const a = new Date(first);
     const b = new Date(last);
     const sameDay =
       a.getFullYear() === b.getFullYear() &&
       a.getMonth() === b.getMonth() &&
       a.getDate() === b.getDate();
     const datePart = a.toLocaleDateString(undefined, {
       month: "short",
       day: "numeric",
     });
     if (sameDay) {
       return `${datePart} ${a.toLocaleTimeString(undefined, {
         hour: "2-digit",
         minute: "2-digit",
       })} → ${b.toLocaleTimeString(undefined, {
         hour: "2-digit",
         minute: "2-digit",
       })}`;
     }
     return `${datePart} → ${b.toLocaleDateString(undefined, {
       month: "short",
       day: "numeric",
     })}`;
   } catch {
     return `${first} → ${last}`;
   }
 }

 function collapseWhitespace(s: string): string {
   return s.replace(/\s+/g, " ").trim();
 }

