import {
  detectGitHubRemote,
  fetchRepoContext,
  fetchRepoContextHistory,
  fetchTeamJudgments,
  listOpenReflexPrs,
  openPrForInsight,
  openPrForJudgment,
  pushJudgmentToRepo,
} from "./github";

  ipcMain.handle("reflex:playground-clear", (_e, sessionId: string) =>
