Index: electron/src/renderer/src/App.tsx
===================================================================
--- electron/src/renderer/src/App.tsx	
+++ electron/src/renderer/src/App.tsx	
@@ -1,392 +1,393 @@
 import { useCallback, useEffect, useMemo, useState } from "react";

 import type {
   CaptureStatus,
   FlowDetail,
   FlowSummary,
   SessionDetail,
   SessionSummary,
 } from "../../shared/types";
 import type { SessionRating } from "../../shared/turn";
 import type {
   RepoInsight,
   RepoSummary,
   SessionJudgment,
 } from "../../shared/judge";
 import { FlowList } from "./components/FlowList";
 import { FlowDetailView } from "./components/FlowDetail";
 import { RepoInsightView } from "./components/RepoInsightView";
 import { RepoList } from "./components/RepoList";
 import { SessionList } from "./components/SessionList";
 import { SessionView } from "./components/SessionView";
 import { SettingsModal } from "./components/SettingsModal";
 import { StatusBar } from "./components/StatusBar";

 type Tab = "sessions" | "repos" | "flows";

 export function App(): JSX.Element {
   const [tab, setTab] = useState<Tab>("sessions");

   // Flows state
   const [flows, setFlows] = useState<FlowSummary[]>([]);
   const [selectedFlowId, setSelectedFlowId] = useState<string | null>(null);
   const [flowDetail, setFlowDetail] = useState<FlowDetail | null>(null);

   // Sessions state
   const [sessions, setSessions] = useState<SessionSummary[]>([]);
   const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
   const [sessionDetail, setSessionDetail] = useState<SessionDetail | null>(null);
   const [ratings, setRatings] = useState<Map<string, SessionRating>>(
     () => new Map(),
   );
   const [selectedRating, setSelectedRating] = useState<SessionRating | null>(
     null,
   );
   const [selectedJudgment, setSelectedJudgment] = useState<SessionJudgment | null>(
     null,
   );
   const [judgmentStale, setJudgmentStale] = useState(false);
   const [hasGemini, setHasGemini] = useState(false);
   const [hasGithub, setHasGithub] = useState(false);
   const [settingsOpen, setSettingsOpen] = useState(false);

   const refreshConfigStatus = useCallback(() => {
     void window.reflex.configStatus().then((c) => {
       setHasGemini(c.has_gemini);
       setHasGithub(c.has_github);
     });
   }, []);

   // Repos state
   const [repos, setRepos] = useState<RepoSummary[]>([]);
   const [selectedRepo, setSelectedRepo] = useState<string | null>(null);
   const [selectedInsight, setSelectedInsight] = useState<RepoInsight | null>(
     null,
   );

   // Global status
   const [status, setStatus] = useState<CaptureStatus | null>(null);

   // Initial data load
   useEffect(() => {
     void window.reflex.listFlows(500).then(setFlows);
     void window.reflex.listSessions(500).then(setSessions);
     void window.reflex.listRatings(1000).then((rs) => {
       const m = new Map<string, SessionRating>();
       for (const r of rs) m.set(r.session_id, r);
       setRatings(m);
     });
     void window.reflex.getStatus().then(setStatus);
     refreshConfigStatus();
     void window.reflex.listRepos().then(setRepos);
   }, [refreshConfigStatus]);

   // First-run: if the user has zero keys configured, pop the settings modal.
   useEffect(() => {
     // Small delay so it doesn't pop before the UI has painted.
     const t = setTimeout(() => {
       if (!hasGemini && !hasGithub) setSettingsOpen(true);
     }, 400);
     return () => clearTimeout(t);
   }, [hasGemini, hasGithub]);

   // Live repo insight updates (triggered after an analyze-repo completes).
   useEffect(() => {
     return window.reflex.onRepoInsight((i) => {
       // Refresh the list so the "ai" badge appears.
       void window.reflex.listRepos().then(setRepos);
       if (selectedRepo === i.repo) setSelectedInsight(i);
     });
   }, [selectedRepo]);

   // Load insight on repo selection
   useEffect(() => {
     if (!selectedRepo) {
       setSelectedInsight(null);
       return;
     }
     void window.reflex
       .getRepoInsight(selectedRepo)
       .then(setSelectedInsight);
   }, [selectedRepo]);

   // When a judgment completes we also want the repos list to refresh
   // (it's possible a new repo just became visible).
   useEffect(() => {
     return window.reflex.onJudgment(() => {
       void window.reflex.listRepos().then(setRepos);
     });
   }, []);

   // Live flow stream
   useEffect(() => {
     return window.reflex.onFlow((flow) => {
       setFlows((prev) => upsert(prev, flow, (f) => f.id));
     });
   }, []);

   // Live session stream
   useEffect(() => {
     return window.reflex.onSession((s) => {
       setSessions((prev) => upsert(prev, s, (x) => x.session_id, (a, b) =>
         new Date(b.last_ts).getTime() - new Date(a.last_ts).getTime(),
       ));
       // If this is the currently selected session, re-fetch details so the
       // detail view gets the newest entries.
       if (selectedSessionId === s.session_id) {
         void window.reflex.getSession(s.session_id).then(setSessionDetail);
       }
     });
   }, [selectedSessionId]);

   // Status updates
   useEffect(() => window.reflex.onStatus(setStatus), []);

   // Live rating stream — update both the list map and, if selected, the detail view.
   useEffect(() => {
     return window.reflex.onRating((r) => {
       setRatings((prev) => {
         const next = new Map(prev);
         next.set(r.session_id, r);
         return next;
       });
       if (selectedSessionId === r.session_id) setSelectedRating(r);
     });
   }, [selectedSessionId]);

   // Load flow detail on selection
   useEffect(() => {
     if (!selectedFlowId) {
       setFlowDetail(null);
       return;
     }
     void window.reflex.getFlow(selectedFlowId).then(setFlowDetail);
   }, [selectedFlowId]);

   // Load session detail + rating + judgment on selection
   useEffect(() => {
     if (!selectedSessionId) {
       setSessionDetail(null);
       setSelectedRating(null);
       setSelectedJudgment(null);
       setJudgmentStale(false);
       return;
     }
     void window.reflex.getSession(selectedSessionId).then(setSessionDetail);
     void window.reflex.getRating(selectedSessionId).then(setSelectedRating);
     void window.reflex.getJudgment(selectedSessionId).then(setSelectedJudgment);
     void window.reflex.judgmentStale(selectedSessionId).then(setJudgmentStale);
   }, [selectedSessionId]);

   // Live judgment stream — cheap because we only emit when a judge call finishes
   useEffect(() => {
     return window.reflex.onJudgment((v) => {
       if (selectedSessionId === v.session_id) {
         setSelectedJudgment(v);
         setJudgmentStale(false);
       }
     });
   }, [selectedSessionId]);

   const handleSelectFlow = useCallback(
     (id: string) => setSelectedFlowId(id),
     [],
   );
   const handleSelectSession = useCallback(
     (id: string) => setSelectedSessionId(id),
     [],
   );

   const [exportStatus, setExportStatus] = useState<string | null>(null);
   const onExport = useCallback(async () => {
     setExportStatus("exporting…");
     try {
       const path = await window.reflex.exportMistakes();
       setExportStatus(`wrote ${path}`);
       setTimeout(() => setExportStatus(null), 4000);
     } catch (e) {
       setExportStatus(`failed: ${(e as Error).message}`);
     }
   }, []);

   const header = useMemo(
     () => (
       <header className="flex h-10 shrink-0 items-center gap-4 border-b border-slate-800 px-4">
         <div className="flex items-center gap-2 text-sm font-medium">
           <span className="inline-block h-2 w-2 rounded-full bg-emerald-500" />
           <span>Reflex</span>
         </div>

         <nav className="flex gap-1 text-xs">
           <TabBtn active={tab === "sessions"} onClick={() => setTab("sessions")}>
             Sessions
             <span className="ml-1.5 text-slate-500">{sessions.length}</span>
           </TabBtn>
           <TabBtn active={tab === "repos"} onClick={() => setTab("repos")}>
             Repos
             <span className="ml-1.5 text-slate-500">{repos.length}</span>
           </TabBtn>
           <TabBtn active={tab === "flows"} onClick={() => setTab("flows")}>
             Flows
             <span className="ml-1.5 text-slate-500">{flows.length}</span>
           </TabBtn>
         </nav>

         <div className="ml-auto flex items-center gap-3 text-xs text-slate-400">
           {exportStatus && <span>{exportStatus}</span>}
           <button
             onClick={onExport}
             className="rounded border border-slate-700 px-2 py-0.5 text-xs hover:bg-slate-800"
             title="Write ~/.reflex/mistakes.md summarising cross-session errors + retries"
           >
             Export mistakes.md
           </button>
           <button
             onClick={() => setSettingsOpen(true)}
             className="flex items-center gap-1 rounded border border-slate-700 px-2 py-0.5 text-xs hover:bg-slate-800"
             title="Settings"
           >
             <span
               className={`inline-block h-1.5 w-1.5 rounded-full ${
                 hasGemini && hasGithub
                   ? "bg-emerald-500"
                   : hasGemini || hasGithub
                     ? "bg-amber-500"
                     : "bg-rose-500"
               }`}
             />
             Settings
           </button>
         </div>
       </header>
     ),
     [
       tab,
       sessions.length,
       flows.length,
       repos.length,
       exportStatus,
       onExport,
       hasGemini,
       hasGithub,
     ],
   );

   const setupBanner =
     !hasGemini || !hasGithub ? (
       <div className="shrink-0 border-b border-amber-700/30 bg-amber-900/20 px-4 py-1.5 text-xs text-amber-200">
         <span>
           {!hasGemini && !hasGithub
             ? "Finish setup: add your Gemini key and GitHub token to judge sessions and open PRs."
             : !hasGemini
               ? "Add your Gemini key to enable AI judging."
               : "Add your GitHub token to open PRs from Reflex."}
         </span>
         <button
           onClick={() => setSettingsOpen(true)}
           className="ml-3 rounded bg-amber-700/40 px-2 py-0.5 text-amber-100 hover:bg-amber-700/70"
         >
           Open settings
         </button>
       </div>
     ) : null;

   return (
     <div className="flex h-full flex-col font-mono text-sm">
       {header}
       {setupBanner}
       <SettingsModal
         open={settingsOpen}
         onClose={() => setSettingsOpen(false)}
         onChanged={refreshConfigStatus}
       />
       <div className="flex min-h-0 flex-1">
         <aside className="w-[420px] shrink-0 overflow-y-auto border-r border-slate-800">
           {tab === "sessions" ? (
             <SessionList
               sessions={sessions}
               ratings={ratings}
               selectedId={selectedSessionId}
               onSelect={handleSelectSession}
             />
           ) : tab === "repos" ? (
             <RepoList
               repos={repos}
               selectedRepo={selectedRepo}
               onSelect={setSelectedRepo}
             />
           ) : (
             <FlowList
               flows={flows}
               selectedId={selectedFlowId}
               onSelect={handleSelectFlow}
             />
           )}
         </aside>
         <main className="min-w-0 flex-1 overflow-y-auto">
           {tab === "sessions" ? (
             <SessionView
               session={sessionDetail}
               rating={selectedRating}
               judgment={selectedJudgment}
               hasGemini={hasGemini}
+              hasGithub={hasGithub}
               judgmentStale={judgmentStale}
               onJudgmentComputed={(v) => {
                 setSelectedJudgment(v);
                 setJudgmentStale(false);
               }}
             />
           ) : tab === "repos" ? (
             <RepoInsightView
               repo={selectedRepo}
               insight={selectedInsight}
               hasGemini={hasGemini}
               hasGithub={hasGithub}
               onAnalyzed={(i) => setSelectedInsight(i)}
             />
           ) : (
             <FlowDetailView flow={flowDetail} />
           )}
         </main>
       </div>
       <StatusBar status={status} />
     </div>
   );
 }

 function TabBtn({
   active,
   onClick,
   children,
 }: {
   active: boolean;
   onClick: () => void;
   children: React.ReactNode;
 }): JSX.Element {
   return (
     <button
       onClick={onClick}
       className={`px-3 py-1 rounded transition ${
         active
           ? "bg-slate-800 text-slate-100"
           : "text-slate-400 hover:text-slate-200 hover:bg-slate-900"
       }`}
     >
       {children}
     </button>
   );
 }

 /** Insert-or-update a list item matched by `keyFn`, keeping the list sorted
  *  by `cmp` (defaults to reverse-insertion order, i.e. newest first). */
 function upsert<T>(
   prev: T[],
   next: T,
   keyFn: (t: T) => string,
   cmp?: (a: T, b: T) => number,
 ): T[] {
   const key = keyFn(next);
   const idx = prev.findIndex((t) => keyFn(t) === key);
   const arr = idx >= 0 ? prev.map((t, i) => (i === idx ? next : t)) : [next, ...prev];
   return cmp ? arr.slice().sort(cmp) : arr.slice(0, 1000);
 }

Index: electron/src/renderer/src/components/ContextTimelinePanel.tsx
===================================================================
--- electron/src/renderer/src/components/ContextTimelinePanel.tsx	
+++ electron/src/renderer/src/components/ContextTimelinePanel.tsx	
@@ -0,0 +1,420 @@
+// Per-session view of the repo's AGENTS.md lifecycle: what the context
+// looks like *right now* in the repo, plus the timeline of commits that
+// have shaped it. Commits that landed after this session's end are
+// highlighted because those are (often) the direct downstream of what
+// Reflex learned from this session.
+
+import { useEffect, useMemo, useState } from "react";
+
+interface TeamContextFile {
+  path: string;
+  content: string;
+  reflex_block: string | null;
+  sha: string;
+  default_branch: string;
+}
+
+interface TeamHistoryEntry {
+  sha: string;
+  short_sha: string;
+  message: string;
+  headline: string;
+  author_login: string | null;
+  author_name: string;
+  author_avatar: string | null;
+  authored_at: string;
+  html_url: string;
+  path: string;
+}
+
+interface TeamOpenPr {
+  number: number;
+  title: string;
+  html_url: string;
+  author_login: string | null;
+  author_avatar: string | null;
+  branch: string;
+  updated_at: string;
+  draft: boolean;
+}
+
+interface Props {
+  /** Local repo path (from judgment.repo); null disables fetching. */
+  repo: string | null;
+  /** This session's last entry timestamp; used to split timeline into
+   *  "before" vs "after this session." */
+  sessionLastTs: string;
+  hasGithub: boolean;
+}
+
+export function ContextTimelinePanel({
+  repo,
+  sessionLastTs,
+  hasGithub,
+}: Props): JSX.Element {
+  const [context, setContext] = useState<TeamContextFile | null>(null);
+  const [history, setHistory] = useState<TeamHistoryEntry[]>([]);
+  const [openPrs, setOpenPrs] = useState<TeamOpenPr[]>([]);
+  const [loading, setLoading] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+
+  const refresh = async (): Promise<void> => {
+    if (!repo || !hasGithub) return;
+    setLoading(true);
+    setError(null);
+    try {
+      const [c, h, p] = await Promise.all([
+        window.reflex.teamContext(repo),
+        window.reflex.teamHistory(repo),
+        window.reflex.teamOpenPrs(repo),
+      ]);
+      setContext(c);
+      setHistory(h);
+      setOpenPrs(p);
+    } catch (e) {
+      setError((e as Error).message);
+    } finally {
+      setLoading(false);
+    }
+  };
+
+  useEffect(() => {
+    void refresh();
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, [repo, hasGithub]);
+
+  // Split history into "after this session" (most interesting — those are
+  // the commits that LANDED as a downstream of this session's learnings)
+  // and "before".
+  const { after, before } = useMemo(() => {
+    const a: TeamHistoryEntry[] = [];
+    const b: TeamHistoryEntry[] = [];
+    for (const h of history) {
+      if (!h.authored_at) {
+        b.push(h);
+        continue;
+      }
+      if (h.authored_at > sessionLastTs) a.push(h);
+      else b.push(h);
+    }
+    return { after: a, before: b };
+  }, [history, sessionLastTs]);
+
+  if (!hasGithub) {
+    return (
+      <EmptyState
+        title="Connect GitHub to see the timeline"
+        body="Open Settings and paste a GitHub token. Reflex will then pull this repo's AGENTS.md history so you can see every time the agent context has changed."
+      />
+    );
+  }
+
+  if (!repo) {
+    return (
+      <EmptyState
+        title="No repo inferred for this session yet"
+        body="Run `Judge with Gemini` on the session first — that's how Reflex figures out which repo this session belonged to."
+      />
+    );
+  }
+
+  return (
+    <div className="p-4">
+      <Header
+        repo={repo}
+        loading={loading}
+        onRefresh={() => void refresh()}
+      />
+
+      {error && (
+        <div className="mt-3 rounded bg-rose-950/40 px-3 py-2 text-xs text-rose-300">
+          {error}
+        </div>
+      )}
+
+      {/* What's live right now */}
+      <Section title="Live agent context in this repo">
+        {context ? (
+          <div>
+            <div className="mb-2 flex flex-wrap items-center gap-2 text-[11px] text-slate-500">
+              <span>
+                file:{" "}
+                <code className="text-slate-300">{context.path}</code>
+              </span>
+              <span>·</span>
+              <span>
+                branch:{" "}
+                <code className="text-slate-300">{context.default_branch}</code>
+              </span>
+              <span>·</span>
+              <span>
+                sha: <code className="text-slate-500">{context.sha.slice(0, 7)}</code>
+              </span>
+              <span>·</span>
+              <span>
+                {context.reflex_block
+                  ? `Reflex block: ${context.reflex_block.length} chars`
+                  : "no Reflex block yet — open a PR to seed it"}
+              </span>
+            </div>
+            {context.reflex_block && (
+              <pre className="selectable max-h-[280px] overflow-auto rounded bg-slate-950 p-3 text-[11px] leading-relaxed text-slate-300">
+                {context.reflex_block}
+              </pre>
+            )}
+          </div>
+        ) : loading ? (
+          <Loading>loading live context…</Loading>
+        ) : (
+          <EmptyInline>
+            No AGENTS.md / CLAUDE.md in this repo yet — open a Reflex PR to
+            seed one.
+          </EmptyInline>
+        )}
+      </Section>
+
+      {/* Open PRs = mid-flight updates */}
+      {openPrs.length > 0 && (
+        <Section title={`Open Reflex PRs (${openPrs.length})`}>
+          <ul className="space-y-1">
+            {openPrs.map((pr) => (
+              <li
+                key={pr.number}
+                className="flex items-center gap-2 rounded border border-slate-800 bg-slate-900/40 px-2 py-1 text-[11px]"
+              >
+                <Avatar
+                  url={pr.author_avatar}
+                  fallback={pr.author_login ?? "?"}
+                />
+                <a
+                  href={pr.html_url}
+                  onClick={(e) => {
+                    e.preventDefault();
+                    window.open(pr.html_url, "_blank", "noopener");
+                  }}
+                  className="truncate text-slate-200 hover:text-sky-300"
+                  title={pr.title}
+                >
+                  #{pr.number} {pr.title}
+                </a>
+                {pr.draft && (
+                  <span className="shrink-0 rounded bg-slate-800 px-1 text-[9px] text-slate-400">
+                    draft
+                  </span>
+                )}
+                <span className="ml-auto shrink-0 text-slate-600">
+                  {pr.author_login ? `@${pr.author_login}` : ""}
+                </span>
+              </li>
+            ))}
+          </ul>
+        </Section>
+      )}
+
+      {/* Timeline */}
+      <Section title={`Context commits (${history.length})`}>
+        {history.length === 0 ? (
+          <EmptyInline>
+            {loading
+              ? "loading…"
+              : "No commits have touched AGENTS.md yet — once a Reflex PR lands, this timeline fills."}
+          </EmptyInline>
+        ) : (
+          <div>
+            {after.length > 0 && (
+              <TimelineGroup
+                label={`After this session (${after.length})`}
+                tone="emerald"
+                entries={after}
+                hint="These are the commits that landed AFTER this session's last turn — typically the downstream of what this session surfaced."
+              />
+            )}
+            {before.length > 0 && (
+              <TimelineGroup
+                label={`Before this session (${before.length})`}
+                tone="slate"
+                entries={before.slice(0, 20)}
+                hint="Earlier context updates — what the agent already knew going into this session."
+              />
+            )}
+          </div>
+        )}
+      </Section>
+    </div>
+  );
+}
+
+// --- subcomponents --------------------------------------------------------
+
+function Header({
+  repo,
+  loading,
+  onRefresh,
+}: {
+  repo: string;
+  loading: boolean;
+  onRefresh: () => void;
+}): JSX.Element {
+  return (
+    <div className="flex items-center gap-2">
+      <span className="inline-block rounded bg-cyan-950 px-1.5 text-[10px] font-semibold uppercase tracking-wide text-cyan-300">
+        Timeline
+      </span>
+      <span className="truncate text-xs text-slate-400" title={repo}>
+        {repo}
+      </span>
+      <button
+        onClick={onRefresh}
+        disabled={loading}
+        className="ml-auto rounded border border-slate-700 px-2 py-0.5 text-[10px] text-slate-300 hover:bg-slate-800 disabled:opacity-50"
+      >
+        {loading ? "refreshing…" : "refresh"}
+      </button>
+    </div>
+  );
+}
+
+function Section({
+  title,
+  children,
+}: {
+  title: string;
+  children: React.ReactNode;
+}): JSX.Element {
+  return (
+    <section className="mt-4">
+      <h3 className="mb-2 text-[10px] font-semibold uppercase tracking-wide text-slate-500">
+        {title}
+      </h3>
+      {children}
+    </section>
+  );
+}
+
+function TimelineGroup({
+  label,
+  tone,
+  entries,
+  hint,
+}: {
+  label: string;
+  tone: "emerald" | "slate";
+  entries: TeamHistoryEntry[];
+  hint: string;
+}): JSX.Element {
+  const pillColor =
+    tone === "emerald"
+      ? "bg-emerald-950 text-emerald-300"
+      : "bg-slate-800 text-slate-400";
+  const lineColor = tone === "emerald" ? "bg-emerald-900" : "bg-slate-800";
+  return (
+    <div className="mb-4">
+      <div className="mb-1 flex items-center gap-2">
+        <span
+          className={`inline-block rounded px-1.5 text-[9px] font-semibold uppercase ${pillColor}`}
+        >
+          {label}
+        </span>
+        <span className="truncate text-[10px] text-slate-600">{hint}</span>
+      </div>
